begin;

update public.curriculum_subjects
set target_tracks = array['경찰직 - 공채(순경)', '경찰직 - 함정요원 항해(순경)', '경찰직 - 함정요원 기관(순경)']::text[],
    sort_order = 3,
    updated_at = now()
where id = 'coast-guard-intro';

update public.curriculum_subjects
set target_tracks = array['경찰직 - 공채(순경)', '경찰직 - 함정요원 항해(순경)', '경찰직 - 함정요원 기관(순경)']::text[],
    sort_order = 4,
    updated_at = now()
where id = 'maritime-law';

on conflict (id) do update set
  name = excluded.name,
  short_name = excluded.short_name,
  tone = excluded.tone,
  target_tracks = excluded.target_tracks,
  sort_order = excluded.sort_order,
  is_published = excluded.is_published,
  is_archived = excluded.is_archived,
  updated_at = now();

on conflict (id) do update set
  subject_id = excluded.subject_id,
  stage_number = excluded.stage_number,
  title = excluded.title,
  sort_order = excluded.sort_order,
  is_published = excluded.is_published,
  requires_wrap_up = excluded.requires_wrap_up,
  updated_at = now();

on conflict (id) do update set
  stage_id = excluded.stage_id,
  lecture_number = excluded.lecture_number,
  title = excluded.title,
  sort_order = excluded.sort_order,
  updated_at = now();

update public.curriculum_stages as stage
set title = lecture_titles.title,
    updated_at = now()
from (
  select stage_id, string_agg(title, ', ' order by sort_order, id) as title
  from public.curriculum_lectures
  group by stage_id
) as lecture_titles
where stage.id = lecture_titles.stage_id
  and stage.subject_id in ('navigation-technique', 'marine-engineering', 'maritime-english');

